export const activityCatalog: ReclaimActivity[] = seeds.map((seed) => ({
  ...seed,
  id: seed.slug,
}));

export const activityCategories: string[] = [...new Set(seeds.map((seed) => seed.category))].sort();

export function findActivity(id: string): ReclaimActivity | undefined {
  return activityCatalog.find((activity) => activity.id === id);
}
